'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies, compare } = require('./src/semver');

// Naive reference: recursive, copies state, same spec semantics.
function ref(registry, root) {
  function step(selected, cons, queue, cursor) {
    if (cursor === queue.length) return selected;
    const name = queue[cursor];
    if (name in selected) return step(selected, cons, queue, cursor + 1);
    const vs = Object.keys(registry[name] || {}).sort((a, b) => compare(b, a))
      .filter(v => cons[name].every(r => satisfies(v, r)));
    for (const v of vs) {
      const sel = { ...selected, [name]: v };
      const c = { ...cons };
      const q = queue.slice();
      let ok = true;
      for (const [d, r] of Object.entries(registry[name][v])) {
        c[d] = (c[d] || []).concat([r]);
        q.push(d);
        if (d in sel && !satisfies(sel[d], r)) { ok = false; break; }
      }
      if (!ok) continue;
      const res = step(sel, c, q, cursor + 1);
      if (res) return res;
    }
    return null;
  }
  const cons = {};
  for (const [n, r] of Object.entries(root)) cons[n] = [r];
  return step({}, cons, Object.keys(root), 0);
}

let seed = 7;
const rnd = n => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };
const names = ['a', 'b', 'c', 'd', 'e', 'f'];
const ver = () => `${rnd(3)}.${rnd(3)}.${rnd(3)}`;
const rng = () => ['^', '~', '>=', '<', ''][rnd(5)] + ver();
for (let t = 0; t < 3000; t += 1) {
  const registry = {};
  for (const n of names.slice(0, 5)) {
    registry[n] = {};
    for (let k = rnd(4); k > 0; k -= 1) {
      const deps = {};
      for (let j = rnd(3); j > 0; j -= 1) deps[names[rnd(6)]] = rng();
      registry[n][ver()] = deps;
    }
  }
  const root = {};
  for (let j = 1 + rnd(2); j > 0; j -= 1) root[names[rnd(5)]] = rng();
  assert.deepEqual(resolve(registry, root), ref(registry, root), JSON.stringify({ registry, root }));
}

// Caret zero-major rules.
assert.equal(satisfies('0.3.0', '^0.2.0'), false);
assert.equal(satisfies('0.2.9', '^0.2.0'), true);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);

// Long chain + cycle, no recursion, no iteration cap.
const N = 50000;
const chain = {};
for (let i = 0; i < N; i += 1) chain[`p${i}`] = { '1.0.0': i + 1 < N ? { [`p${i + 1}`]: '^1.0.0' } : { p0: '1.0.0' } };
const out = resolve(chain, { p0: '*' });
assert.equal(Object.keys(out).length, N);

// Backtracking: newest x conflicts, older works.
assert.deepEqual(resolve({ x: { '2.0.0': { y: '^2.0.0' }, '1.0.0': { y: '^1.0.0' } }, y: { '1.5.0': {} } }, { x: '*', y: '*' }),
  { x: '1.0.0', y: '1.5.0' });
assert.equal(resolve({}, { missing: '*' }), null);
assert.deepEqual(resolve({}, {}), {});
assert.throws(() => resolve({ z: { '01.0.0': {} } }, {}), TypeError);
assert.deepEqual(resolve({ __proto__: null, ['__proto__']: { '1.0.0': {} } }, JSON.parse('{"__proto__":"*"}')), JSON.parse('{"__proto__":"1.0.0"}'));
console.log('ok');
